def transform(grid):
    a = np.array(grid)
    H, W = a.shape
    ys, xs = np.where(a == 4)
    y0, x0 = ys.min(), xs.min()
    m = a[y0:ys.max() + 1, x0:xs.max() + 1]

    # all 8 orientations of the motif, de-duplicated
    tfs = []
    seen = set()
    for k in range(4):
        r = np.rot90(m, k)
        for t in (r, r[:, ::-1]):
            key = (t.shape, t.tobytes())
            if key not in seen:
                seen.add(key)
                tfs.append(t.copy())

    out = a.copy()
    found = []
    for t in tfs:
        h, w = t.shape
        for y in range(-h + 1, H):
            for x in range(-w + 1, W):
                if (y, x) == (y0, x0) and np.array_equal(t, m):
                    continue
                ok = True
                for dy in range(h):
                    for dx in range(w):
                        yy, xx = y + dy, x + dx
                        inside = 0 <= yy < H and 0 <= xx < W
                        if t[dy, dx] == 6:
                            if not inside or a[yy, xx] != 6:
                                ok = False
                        elif inside and a[yy, xx] in (6, 4):
                            ok = False
                        if not ok:
                            break
                    if not ok:
                        break
                if ok:
                    found.append((y, x, t))

    for (y, x, t) in found:
        h, w = t.shape
        for dy in range(h):
            for dx in range(w):
                yy, xx = y + dy, x + dx
                if t[dy, dx] == 4 and 0 <= yy < H and 0 <= xx < W:
                    out[yy, xx] = 4
        emit(out, f"Found a rotated/mirrored copy of the motif's 6-pattern at box ({y},{x}); painted its 4-cells.")

    emit(out, "All copies of the 6-pattern now carry the motif's 4s.")
    return out
